from fractions import Fraction as F
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
tests='TUVW'; modes='ABCD'
cost=[F('1.8'),F('1.5'),F('1.2'),F('0.8')]
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def stop(ids):
 w=sum(rows[i][1] for i in ids)
 return min((F(sum(rows[i][1]*loss[a][modes.index(rows[i][0])] for i in ids),w),modes[a]) for a in range(4))
def solve(ids,available,n):
 best=stop(ids)
 if n:
  for t in available:
   v=cost[t]; w=sum(rows[i][1] for i in ids)
   for b in (0,1):
    sub=tuple(i for i in ids if rows[i][2][t]==b)
    if sub:v+=F(sum(rows[i][1] for i in sub),w)*solve(sub,tuple(j for j in available if j!=t),n-1)[0]
   best=min(best,(v,tests[t]))
 return best
ids=tuple(range(8)); total=sum(r[1] for r in rows)
values={'STOP':float(stop(ids)[0])}
for t in range(4):
 v=cost[t]
 for b in (0,1):
  sub=tuple(i for i in ids if rows[i][2][t]==b)
  if sub:v+=F(sum(rows[i][1] for i in sub),total)*solve(sub,tuple(j for j in range(4) if j!=t),1)[0]
 values[tests[t]]=float(v)
best=solve(ids,tuple(range(4)),2)
nexts={}
if best[1] in tests:
 t=tests.index(best[1])
 for b in (0,1):
  sub=tuple(i for i in ids if rows[i][2][t]==b)
  nexts[str(b)]=solve(sub,tuple(j for j in range(4) if j!=t),1)[1] if sub else 'IMPOSSIBLE'
import json
print(json.dumps({'first':best[1],'first_losses':values,'next':nexts}))

